INSERT INTO "Patchnote" ("version", "type", "date", "titleEn", "titleFr", "entries") VALUES
('0.8.7', 'patch', '2026-08-05T12:00:00.000Z', 'Fix: plugins that store data now work in Docker', 'Correctif : les plugins qui stockent des données fonctionnent en Docker', '[{"type":"fix","titleEn":"Plugins with their own storage load again","titleFr":"Les plugins avec stockage se chargent enfin","descEn":"In Docker, any plugin declaring the storage capability crashed on startup. Affected every image published so far — if one of your plugins refused to load, it was not at fault.","descFr":"En Docker, tout plugin déclarant la capacité de stockage plantait au démarrage. Toutes les images publiées jusqu''ici étaient concernées — si un de tes plugins refusait de se charger, il n''y était pour rien."},{"type":"fix","titleEn":"Plugin installs no longer fail silently","titleFr":"L''installation de plugins n''échoue plus en silence","descEn":"When GitHub rate-limited us, Oscarr installed the wrong archive and the plugin broke later. It now says so instead, and refuses an incomplete archive.","descFr":"Quand GitHub nous limitait, Oscarr installait la mauvaise archive et le plugin cassait plus tard. Il le signale désormais, et refuse une archive incomplète."},{"type":"fix","titleEn":"Install errors stay on screen","titleFr":"Les erreurs d''installation restent affichées","descEn":"They now appear inside the dialog instead of behind it, and no longer vanish after a few seconds.","descFr":"Elles s''affichent dans la fenêtre au lieu d''être masquées derrière, et ne disparaissent plus au bout de quelques secondes."}]')
ON CONFLICT ("version") DO NOTHING;
